 if(x=f("g_reg")){x.k="Each crane: annual thorough exam ≤ 12 months · load test ≤ 5 years (1.25×SWL ≤20 t; SWL+5 t ≤50 t; 1.1×SWL >50 t) · SWL on jib = register · limit switches";x.kg="Κάθε γερανός: ετήσια ≤ 12 μήνες · load test ≤ 5 χρόνια (1,25×SWL ≤20t· SWL+5t ≤50t· 1,1×SWL >50t) · SWL = register · limit switches";x.r="ILO C152 · SOLAS II-1/3-13 · MSC.1/Circ.1663 (existing cranes by first renewal survey after 1 Jan 2026; valid ILO 152 certs accepted)";}
 if(x=f("g_loose")){x.k="Proof test: hooks/shackles 2×SWL (≤25 t), grabs 2×SWL (≤10 t) · inspect before every use · random check 3 items → certificates";x.kg="Proof test: hooks/shackles 2×SWL, grabs 2×SWL · έλεγχος πριν από κάθε χρήση · τυχαίος έλεγχος 3 κομματιών → certs";}
